// What a host receives instead of a run report.
//
// The answer prompt imposes no citation format (see tests/pipeline/answer.test.ts), so the model
// refers to skeleton node ids -- "[8b]" -- rather than file:line. The benchmark resolves those
// against the recap its report carries; a host has no report, so the mapping has to travel with
// the answer or every reference in it is unverifiable. Built from the trace, costing no request.
interface ReadMaterial {
    nodeId: string;
    file: string;
    startLine: number;
    endLine: number;
}

export function formatToolResult(answer: string, materials: ReadMaterial[]): string {
    if (materials.length === 0) return answer;
    const lines = materials.map(m => `  ${m.nodeId}  ${m.file}:${m.startLine}-${m.endLine}`);
    return `${answer}\n\n---\nRead (node -> source):\n${lines.join('\n')}`;
}

// Both conditions are knowable before a single Gemini request is sent, and both would otherwise
// surface as a spent-quota failure: a missing index sinks the run after routing has been paid
// for, and a missing key fails with API_KEY_INVALID only once the request is on the wire.
export function preflightMessage(shardCount: number, apiKey: string | undefined): string | null {
    if (shardCount === 0) {
        return 'The definition index is missing. Build it with `npm run prewarm` '
            + '(it needs ../Rocket.Chat, or $ROCKET_CHAT_SRC pointing at the repo), then restart this server.';
    }
    if (!apiKey) {
        return 'GEMINI_API_KEY is not set. Put it in the project `.env`, then restart this server.';
    }
    return null;
}

// Serialises tool calls so a host that emits several in one message cannot fire three questions'
// worth of Gemini requests at once. The free-tier ceiling is requests per minute, and a 429
// arrives only after the quota is already spent -- queueing is the one form of throttling that
// wastes nothing.
const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));

export function createSerialQueue(spacingMs: number) {
    // The tail is deliberately a promise that never rejects: a failing job must reject its own
    // caller without breaking the chain for everyone queued behind it.
    let tail: Promise<unknown> = Promise.resolve();
    return function enqueue<T>(job: () => Promise<T>): Promise<T> {
        const result = tail.then(job);
        tail = result.then(() => sleep(spacingMs), () => sleep(spacingMs));
        return result;
    };
}

