#!/usr/bin/env npx tsx
// stdio MCP entry. One tool, one question per call, three Gemini requests inside -- the same
// pipeline the benchmark runs, reached from a second door.
//
// stdout belongs to the JSON-RPC framing: every diagnostic here goes to stderr. A single stray
// console.log would corrupt the protocol stream.
import '../eval/utils/load-env.js';   // side effect: .env -> process.env, before GeminiClient reads the key
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { z } from 'zod';
import { loadIndex } from '../indexer/load.js';
import { loadAllSections } from '../deepwiki/sections.js';
import { runQuestion } from '../pipeline/run.js';
import { GeminiClient } from '../pipeline/llm.js';
import { createSerialQueue } from './queue.js';
import { preflightMessage } from './preflight.js';
import { formatToolResult } from './format.js';

// Same throttle constant as the benchmark loop: one question's three requests, then a pause.
const SPACING_MS = 6000;

const shardCount = loadIndex();
const blocked = preflightMessage(shardCount, process.env.GEMINI_API_KEY);
// The index and the wiki sections are read once and stay resident (~50M, the same as one
// benchmark run). Loading them per call would re-read every shard for every question.
const sections = blocked ? [] : loadAllSections();
console.error(blocked ? `mcp: not ready -- ${blocked}` : `mcp: ready, ${shardCount} shards, ${sections.length} sections`);

const enqueue = createSerialQueue(SPACING_MS);
let seq = 0;

const server = new McpServer({ name: 'rocket-chat-code-analyzer', version: '2.0.0' });

server.registerTool(
    'ask_codebase',
    {
        title: 'Ask the Rocket.Chat codebase',
        description:
            'Answer a question about the Rocket.Chat codebase -- where something lives, how a '
            + 'mechanism works, what crosses subsystems. Returns prose with file:line citations. '
            + 'One call costs three LLM requests and takes tens of seconds; calls are queued and '
            + 'run one at a time.',
        inputSchema: { question: z.string().min(1).describe('A natural-language question about the Rocket.Chat codebase.') },
    },
    async ({ question }) => {
        if (blocked) return { content: [{ type: 'text' as const, text: blocked }], isError: true };
        return enqueue(async () => {
            const qid = `mcp-${++seq}`;
            console.error(`[${qid}] ${question}`);
            try {
                // No deepwikiFn: the baseline is the benchmark report's comparison column.
                const row = await runQuestion(qid, question, { llm: new GeminiClient(), sections });
                const text = formatToolResult(row.answer, row.trace.reading.materials);
                return { content: [{ type: 'text' as const, text }] };
            } catch (e) {
                const text = `Failed to answer: ${e instanceof Error ? e.message : String(e)}`;
                console.error(`[${qid}] ${text}`);
                return { content: [{ type: 'text' as const, text }], isError: true };
            }
        });
    },
);

await server.connect(new StdioServerTransport());

// LlmClient boundary: the pipeline depends on this interface only, so every stage is
// testable with FakeLlm and the free-tier request budget is metered in one place.
import { GoogleGenerativeAI } from '@google/generative-ai';

export const estimateTokens = (text: string): number => Math.ceil(text.length / 4);

export interface LlmClient {
    generate(prompt: string): Promise<string>;
    readonly calls: number;
    readonly promptTokensEst: number;
}

export class FakeLlm implements LlmClient {
    calls = 0;
    promptTokensEst = 0;
    constructor(private replies: string[]) {}
    async generate(prompt: string): Promise<string> {
        this.calls++;
        this.promptTokensEst += estimateTokens(prompt);
        const r = this.replies.shift();
        if (r === undefined) throw new Error('FakeLlm: no more queued replies');
        return r;
    }
}

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));

export class GeminiClient implements LlmClient {
    calls = 0;
    promptTokensEst = 0;
    private model;
    constructor(modelName = process.env.GEMINI_MODEL || 'gemini-2.5-flash') {
        const key = process.env.GEMINI_API_KEY;
        if (!key) throw new Error('GEMINI_API_KEY missing (put it in .env)');
        this.model = new GoogleGenerativeAI(key).getGenerativeModel({ model: modelName, generationConfig: { temperature: 0 } });
    }
    async generate(prompt: string): Promise<string> {
        this.calls++;
        this.promptTokensEst += estimateTokens(prompt);
        let lastErr: unknown;
        for (let attempt = 0; attempt < 4; attempt++) {
            try {
                const res = await this.model.generateContent(prompt);
                return res.response.text();
            } catch (e: any) {
                lastErr = e;
                const status = e?.status ?? e?.response?.status;
                if (status && status !== 429 && status < 500) throw e; // real errors: fail fast
                await sleep(2000 * 2 ** attempt); // 429/5xx/transient: backoff
            }
        }
        throw lastErr;
    }
}

// Shared transport for DeepWiki's official MCP endpoint (JSON-RPC 2.0 over HTTP).
// The endpoint may reply with a plain JSON body or Server-Sent Events (multiple
// "data:" lines, e.g. progress/notification frames followed by the actual
// tools/call result) — both are handled here.
export const MCP_ENDPOINT = 'https://mcp.deepwiki.com/mcp';

// Parse an MCP HTTP response body into the joined text of its result content.
// Exported as a pure function so response-shape edge cases can be unit tested
// without a live network call.
//
// SSE bodies can carry several "data:" lines (e.g. a notification frame before
// the actual JSON-RPC result), so every line is parsed and the first one that
// looks like a JSON-RPC response (has `result` or `error`) is used — not just
// the first "data:" line. A `result.content` array can hold several text
// items; all of them are joined, not just the first.
export function parseMcpResponse(bodyText: string, toolName: string): string {
    const dataLines = bodyText.split('\n').filter(line => line.startsWith('data:'));
    const candidateTexts = dataLines.length > 0
        ? dataLines.map(line => line.slice('data:'.length).trim())
        : [bodyText.trim()];

    let payload: any;
    for (const candidateText of candidateTexts) {
        if (!candidateText) continue;
        let parsed: any;
        try { parsed = JSON.parse(candidateText); } catch { continue; }
        if (parsed && (parsed.result !== undefined || parsed.error !== undefined)) {
            payload = parsed;
            break;
        }
    }
    if (payload === undefined) {
        throw new Error(`MCP tool ${toolName} returned an unparseable response: ${bodyText.slice(0, 300)}`);
    }
    if (payload.error) {
        throw new Error(`MCP tool ${toolName} returned an error: ${JSON.stringify(payload.error)}`);
    }

    const content = payload.result?.content;
    const text = Array.isArray(content)
        ? content
            .filter((c: any) => c && (c.type === 'text' || typeof c.text === 'string'))
            .map((c: any) => c.text)
            .join('\n')
        : '';
    if (!text) {
        throw new Error(`MCP tool ${toolName} returned no text content: ${JSON.stringify(payload).slice(0, 300)}`);
    }
    return text;
}

// Call an MCP tool via JSON-RPC 2.0 tools/call and return its joined text content.
export async function callMcpTool(name: string, args: Record<string, unknown>): Promise<string> {
    const res = await fetch(MCP_ENDPOINT, {
        method: 'POST',
        headers: {
            'content-type': 'application/json',
            accept: 'application/json, text/event-stream',
        },
        body: JSON.stringify({
            jsonrpc: '2.0',
            id: Date.now(),
            method: 'tools/call',
            params: { name, arguments: args },
        }),
    });
    if (!res.ok) throw new Error(`MCP request for ${name} failed: HTTP ${res.status}`);
    const raw = await res.text();
    return parseMcpResponse(raw, name);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { DATA_DIR, GRAPH_DIR, OUTPUT_DIR, GENERATOR_VERSION, isIndexedSourceFile } from '../src/config.js';

test('config: paths are correct, and the version marks the artefact format', () => {
    assert.ok(DATA_DIR.endsWith('/data'), `DATA_DIR=${DATA_DIR}`);
    assert.ok(OUTPUT_DIR.endsWith('/output.nosync'), `OUTPUT_DIR=${OUTPUT_DIR}`);
    assert.ok(GRAPH_DIR.endsWith('/output.nosync/graph'), `GRAPH_DIR=${GRAPH_DIR}`);

    // '12' is the shard format, and the calibration marker inside keyspaceScope
    // (`repo@extractor-v12`). It no longer invalidates a cache: buildGraph clears the graph
    // directory and rebuilds every time without reading this.
    assert.equal(GENERATOR_VERSION, '12');
});

test('isIndexedSourceFile: plain .ts / .tsx / .js pass', () => {
    assert.equal(isIndexedSourceFile('apps/meteor/server/foo.ts'), true);
    assert.equal(isIndexedSourceFile('apps/meteor/client/Bar.tsx'), true);
    assert.equal(isIndexedSourceFile('apps/meteor/server/baz.js'), true);
});

test('isIndexedSourceFile: same extensions but scanDirectory-excluded patterns are rejected', () => {
    assert.equal(isIndexedSourceFile('apps/meteor/server/foo.d.ts'), false);
    assert.equal(isIndexedSourceFile('apps/meteor/server/foo.test.ts'), false);
    assert.equal(isIndexedSourceFile('apps/meteor/client/Bar.spec.tsx'), false);
    assert.equal(isIndexedSourceFile('apps/meteor/public/vendor.min.js'), false);
});

test('isIndexedSourceFile: node_modules and dist paths are rejected', () => {
    assert.equal(isIndexedSourceFile('apps/meteor/node_modules/lib/index.ts'), false);
    assert.equal(isIndexedSourceFile('apps/meteor/dist/bundle.js'), false);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import * as fs from 'fs';
import { askDeepWiki } from '../../src/deepwiki/ask.js';

test('askDeepWiki caches: second call does not hit the network', async () => {
    const dir = 'data/deepwiki/answers';
    fs.rmSync(`${dir}/test-q.md`, { force: true });
    let hits = 0;
    const postFn = async () => { hits++; return 'DeepWiki says: because.'; };
    const a1 = await askDeepWiki('test-q', 'why?', { postFn });
    const a2 = await askDeepWiki('test-q', 'why?', { postFn });
    assert.equal(a1, 'DeepWiki says: because.');
    assert.equal(a2, a1);
    assert.equal(hits, 1);
    fs.rmSync(`${dir}/test-q.md`, { force: true });
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { parseSections, loadAllSections } from '../../src/deepwiki/sections.js';

const MD = [
    'preamble before any heading, cites [pre/amble.ts:1]() which must be ignored',
    '',
    '## Purpose and Scope',
    'Pure prose, no citations at all.',
    '',
    '## Message Sending Workflow',
    'The flow starts in [apps/meteor/client/lib/chats/flows/sendMessage.ts:59-120]().',
    'It then calls [apps/meteor/app/lib/client/methods/sendMessage.ts:12]().',
    'A repeat of [apps/meteor/client/lib/chats/flows/sendMessage.ts:200]() must not duplicate.',
    '',
    '### Optimistic Update',
    'Handled by [apps/meteor/client/lib/optimistic.ts:5-40]().',
    '',
    '## Relevant source files',
    '- [apps/meteor/package.json](apps/meteor/package.json)',
].join('\n');

test('parseSections attributes citations to the heading they appear under', () => {
    const secs = parseSections('2.2-core-application', MD);
    assert.deepEqual(secs.map(s => s.heading), ['Message Sending Workflow', 'Optimistic Update']);
    assert.deepEqual(secs[0].sources, [
        'apps/meteor/client/lib/chats/flows/sendMessage.ts',
        'apps/meteor/app/lib/client/methods/sendMessage.ts',
    ]);
    assert.deepEqual(secs[1].sources, ['apps/meteor/client/lib/optimistic.ts']);
});

test('parseSections drops prose-only subsections and the page preamble', () => {
    const secs = parseSections('p', MD);
    assert.ok(!secs.some(s => s.heading === 'Purpose and Scope'));
    assert.ok(!secs.some(s => s.sources.includes('pre/amble.ts')));
});

// The page header's `- [path](path)` bullet list is page-wide and carries no line anchor, so it
// must not be mistaken for a subsection-scoped citation.
test('parseSections ignores the page-level bullet list of relevant files', () => {
    const secs = parseSections('p', MD);
    assert.ok(!secs.some(s => s.heading === 'Relevant source files'));
});

test('parseSections builds a page-qualified path and keeps the subsection prose', () => {
    const secs = parseSections('2.2-core-application', MD);
    assert.equal(secs[0].path, '2.2-core-application › Message Sending Workflow');
    assert.ok(secs[0].prose.includes('The flow starts in'));
    assert.ok(!secs[0].prose.includes('Handled by'));      // stops at the next heading
});

test('loadAllSections reads a directory of pages', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'secs-'));
    fs.writeFileSync(path.join(dir, 'a-page.md'), '## S\ncites [x/y.ts:1]()\n');
    fs.writeFileSync(path.join(dir, 'b-page.md'), '## T\ncites [z/w.ts:2]()\n');
    const all = loadAllSections(dir);
    assert.deepEqual(all.map(s => s.path), ['a-page › S', 'b-page › T']);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buildSelectPrompt, parseSelectReply, selectChains } from '../../src/pipeline/select.js';
import { FakeLlm } from '../../src/pipeline/llm.js';
import type { Chain } from '../../src/pipeline/types.js';

const chain = (id: number, label: string, tied = false): Chain =>
    ({ id, pageId: 'p', sections: ['p › S'], label, seed: { symbol: 's' + id, file: 'f.ts' }, score: 1, tied, prose: '' });
const chains = [
    chain(1, '2.2 › Message Sending Workflow · sendMessage'),
    chain(2, '2.4 › Message Composer Popups · RoomMessageContent', true),
    chain(3, '3.5 › System Architecture · encryptMessage', true),
];

test('buildSelectPrompt lists every chain and the whole skeleton', () => {
    const p = buildSelectPrompt('how is a message sent?', 'SKELETON-TEXT', chains);
    assert.ok(p.includes('Chain 1: 2.2 › Message Sending Workflow · sendMessage'));
    assert.ok(p.includes('tied seed'));                    // tied chains are flagged
    assert.ok(p.includes('SKELETON-TEXT'));
    assert.ok(p.includes('how is a message sent?'));
});

test('parseSelectReply keeps known ids in reply order and reports the rest as dropped', () => {
    const r = parseSelectReply('3, 1', chains);
    assert.deepEqual(r.kept, [3, 1]);
    assert.deepEqual(r.dropped, [2]);
});

test('parseSelectReply ignores unknown ids and duplicates', () => {
    assert.deepEqual(parseSelectReply('1\n1\n9\n2', chains).kept, [1, 2]);
});

test('parseSelectReply tolerates prose around the numbers', () => {
    assert.deepEqual(parseSelectReply('keep chain 1 and chain 3.', chains).kept, [1, 3]);
});

// Dropping is irreversible, so an unparseable reply must not cost the run all of its material.
test('parseSelectReply keeps everything when it can find no valid id', () => {
    const r = parseSelectReply('I am not sure which chains matter.', chains);
    assert.deepEqual(r.kept, [1, 2, 3]);
    assert.deepEqual(r.dropped, []);
});

test('selectChains returns the raw reply alongside the decision', async () => {
    const r = await selectChains('q', 'SK', chains, new FakeLlm(['1']));
    assert.deepEqual(r.kept, [1]);
    assert.deepEqual(r.dropped, [2, 3]);
    assert.equal(r.raw, '1');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { packMaterials } from '../../src/pipeline/reading.js';
import { GLOBAL_INDEX } from '../../src/indexer/state.js';
import type { SkeletonNode } from '../../src/pipeline/types.js';

const node = (id: string, sym: string): SkeletonNode => ({ id, symbol: sym, file: 'f/' + sym + '.ts', line: 10, snippet: '', kind: 'major', direction: 'down', edgeType: null, children: [] });
const table = new Map([['1a', node('1a', 'big')], ['1b', node('1b', 'small')], ['2a', node('2a', 'other')]]);
const readFn = (n: SkeletonNode) => ({ text: n.symbol === 'big' ? 'x'.repeat(4000) : 'y'.repeat(400), startLine: 10, endLine: 20 });

// Single global ceiling, no per-chain quota: read in order until the cap, then stop and record.
test('packMaterials reads the whole order when the ceiling allows', () => {
    const { materials, unread, cappedOut } = packMaterials(['1a', '1b', '2a'], table, 100000, { readFn });
    assert.deepEqual(materials.map(m => m.nodeId), ['1a', '1b', '2a']);
    assert.deepEqual(unread, []);
    assert.equal(cappedOut, false);
});

test('packMaterials stops at the ceiling and records what it never read', () => {
    const { materials, unread, cappedOut } = packMaterials(['1a', '1b', '2a'], table, 250, { readFn });
    assert.ok(materials.reduce((a, m) => a + m.tokens, 0) <= 250);
    assert.ok(unread.length > 0);
    assert.equal(cappedOut, true);
    assert.deepEqual([...materials.map(m => m.nodeId), ...unread].sort(), ['1a', '1b', '2a']);
});

test('packMaterials records ids whose read failed outright', () => {
    const { materials, unread } = packMaterials(['1a', '1b'], table, 100000, { readFn: n => n.id === '1b' ? null : readFn(n) });
    assert.deepEqual(materials.map(m => m.nodeId), ['1a']);
    assert.deepEqual(unread, ['1b']);
});

test('packMaterials packs a repeated id once', () => {
    const { materials } = packMaterials(['1a', '1a', '1b'], table, 100000, { readFn });
    assert.deepEqual(materials.map(m => m.nodeId), ['1a', '1b']);
});

test('a node with no definition id reads nothing rather than guessing a file', () => {
    // The default read this replaces took files[0] for the bare name and returned a blind 60-line
    // window, handed to the model as that symbol's implementation with no signal it was a guess.
    // Reading nothing is the honest outcome, and it lands in `unread` where attribution sees it.
    const orphan = node('9z', 'orphan');
    delete (orphan as { defId?: string }).defId;

    const { materials, unread } = packMaterials(['9z'], new Map([['9z', orphan]]), 24000);

    assert.deepEqual(materials, []);
    assert.deepEqual(unread, ['9z']);
});

import { test, beforeEach } from 'node:test';
import assert from 'node:assert/strict';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { GLOBAL_INDEX, resetGlobalIndex } from '../../src/indexer/state.js';
import { readDefinition } from '../../src/engine/source-defs.js';
import type { Def } from '../../src/indexer/defs.js';

const root = fs.mkdtempSync(path.join(os.tmpdir(), 'src-'));
const write = (rel: string, body: string) => {
    const abs = path.join(root, rel);
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    fs.writeFileSync(abs, body);
};
const def = (o: Partial<Def> & Pick<Def, 'id' | 'file' | 'line' | 'endLine'>): Def => ({
    name: o.id.split('#')[1], qualifiedName: o.id.split('#')[1], kind: 'function',
    signature: '', exported: true, ...o,
} as Def);

beforeEach(() => resetGlobalIndex());

test('an implementation is read from the definition line range, with no name lookup', () => {
    write('src/a.ts', ['// header', 'export function target() {', '  return 42;', '}', 'export function other() {}'].join('\n'));
    GLOBAL_INDEX.defs.set('src/a.ts#target', def({ id: 'src/a.ts#target', file: 'src/a.ts', line: 2, endLine: 4 }));

    const impl = readDefinition('src/a.ts#target', root)!;

    assert.equal(impl.startLine, 2);
    assert.equal(impl.endLine, 4);
    assert.match(impl.text, /return 42/);
    assert.ok(!impl.text.includes('other'));
});

test('two same-named definitions read their own bodies', () => {
    write('src/rsa.ts', ['export function encrypt() {', '  return "rsa";', '}'].join('\n'));
    write('src/aes.ts', ['export function encrypt() {', '  return "aes";', '}'].join('\n'));
    GLOBAL_INDEX.defs.set('src/rsa.ts#encrypt', def({ id: 'src/rsa.ts#encrypt', file: 'src/rsa.ts', line: 1, endLine: 3 }));
    GLOBAL_INDEX.defs.set('src/aes.ts#encrypt', def({ id: 'src/aes.ts#encrypt', file: 'src/aes.ts', line: 1, endLine: 3 }));

    // The reading layer had its own name->file guess, distinct from the traversal's, so a
    // correctly anchored skeleton could still be handed the other file's body.
    assert.match(readDefinition('src/rsa.ts#encrypt', root)!.text, /rsa/);
    assert.match(readDefinition('src/aes.ts#encrypt', root)!.text, /aes/);
});

test('an unknown definition returns null instead of guessing a file', () => {
    assert.equal(readDefinition('src/nope.ts#missing', root), null);
});

test('a definition whose file has since shrunk is clamped, not thrown', () => {
    write('src/short.ts', 'export const a = 1;\n');
    GLOBAL_INDEX.defs.set('src/short.ts#a', def({ id: 'src/short.ts#a', file: 'src/short.ts', line: 1, endLine: 999 }));

    const impl = readDefinition('src/short.ts#a', root)!;

    assert.equal(impl.startLine, 1);
    assert.ok(impl.endLine <= 2);
});

test('a dispatch node has no body to read', () => {
    assert.equal(readDefinition('#dispatch/callbacks/afterSave', root), null);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buildRoutingPrompt, parseRoutingReply, route } from '../../src/pipeline/routing.js';
import { FakeLlm } from '../../src/pipeline/llm.js';
import type { WikiSubsection } from '../../src/deepwiki/sections.js';

const sec = (pageId: string, heading: string): WikiSubsection =>
    ({ pageId, heading, path: `${pageId} › ${heading}`, sources: ['x.ts'], prose: '' });

const sections = [
    sec('2.2-core-application', 'Message Sending Workflow'),
    sec('2.2-core-application', 'Room Navigation and Opening Flow'),
    sec('6.2-messaging-and-room-apis', 'Data Flow: Sending a Message'),
    sec('2.4-ui-component-system', 'Overview'),
    sec('3.5-end-to-end-encryption', 'Overview'),
];

test('buildRoutingPrompt lists subsection paths and the question, never page blurbs', () => {
    const p = buildRoutingPrompt('how is a message sent?', sections);
    assert.ok(p.includes('2.2-core-application › Message Sending Workflow'));
    assert.ok(p.includes('6.2-messaging-and-room-apis › Data Flow: Sending a Message'));
    assert.ok(p.includes('how is a message sent?'));
    assert.ok(!/blurb/i.test(p));
});

test('parseRoutingReply matches full paths in order, ignoring duplicates and unknowns', () => {
    const r = parseRoutingReply(
        '2.2-core-application › Message Sending Workflow\nnope › nothing\n6.2-messaging-and-room-apis › Data Flow: Sending a Message\n2.2-core-application › Message Sending Workflow',
        sections);
    assert.deepEqual(r.map(x => x.path), [
        '2.2-core-application › Message Sending Workflow',
        '6.2-messaging-and-room-apis › Data Flow: Sending a Message',
    ]);
    assert.deepEqual(r.map(x => x.rank), [1, 2]);
});

// Headings repeat across pages ("Overview" appears in both 2.4 and 3.5), so a bare heading is
// ambiguous and must never match on its own.
test('parseRoutingReply requires the page-qualified path, not a bare heading', () => {
    assert.deepEqual(parseRoutingReply('Overview', sections), []);
    assert.deepEqual(parseRoutingReply('3.5-end-to-end-encryption › Overview', sections).map(x => x.path),
        ['3.5-end-to-end-encryption › Overview']);
});

test('parseRoutingReply tolerates decoration around the path', () => {
    const r = parseRoutingReply('1. `2.2-core-application › Message Sending Workflow` — most relevant', sections);
    assert.deepEqual(r.map(x => x.path), ['2.2-core-application › Message Sending Workflow']);
});

test('route returns [] when the model names nothing valid', async () => {
    assert.deepEqual(await route('q', sections, new FakeLlm(['I am not sure.'])), []);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { readIndexMeta, writeIndexMeta } from '../../src/indexer/meta.js';
import { GENERATOR_VERSION } from '../../src/config.js';

function tmpMetaPath(): string {
    return path.join(os.tmpdir(), `meta-${process.pid}-${Math.round(process.hrtime()[1])}.json`);
}

test('meta: returns null when the file does not exist', () => {
    const p = tmpMetaPath();
    assert.equal(readIndexMeta(p), null);
});

test('meta: reads back exactly what was written, stamped with the current GENERATOR_VERSION', () => {
    const p = tmpMetaPath();
    try {
        writeIndexMeta('abc123', '2026-08-09T00:00:00.000Z', p);
        const m = readIndexMeta(p);
        assert.ok(m, 'should read back');
        assert.equal(m!.targetCommit, 'abc123');
        assert.equal(m!.generatorVersion, GENERATOR_VERSION);
        assert.equal(m!.builtAt, '2026-08-09T00:00:00.000Z');
    } finally {
        fs.rmSync(p, { force: true });
    }
});

test('meta: targetCommit may be null (the target is not a git repository)', () => {
    const p = tmpMetaPath();
    try {
        writeIndexMeta(null, '2026-08-09T00:00:00.000Z', p);
        assert.equal(readIndexMeta(p)!.targetCommit, null);
    } finally {
        fs.rmSync(p, { force: true });
    }
});

test('meta: returns null on a corrupt file rather than throwing', () => {
    const p = tmpMetaPath();
    try {
        fs.writeFileSync(p, '{ this is not json');
        assert.equal(readIndexMeta(p), null);
    } finally {
        fs.rmSync(p, { force: true });
    }
});

test('meta: a missing generatorVersion field is treated as invalid', () => {
    const p = tmpMetaPath();
    try {
        fs.writeFileSync(p, JSON.stringify({ targetCommit: 'abc' }));
        assert.equal(readIndexMeta(p), null);
    } finally {
        fs.rmSync(p, { force: true });
    }
});
